const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s); const fmt=n=>(n===null||n===undefined||n==='')?'—':Number(n).toLocaleString(undefined,{maximumFractionDigits:2});
let activeDataset={dataset_id:null,competition_id:null,season_id:null,label:'Select current dataset',provider:'FIL'};
let activeCapabilities={};
function datasetUrl(p){if(!activeDataset.dataset_id)return p;const u=new URL(p,location.origin);u.searchParams.set('dataset_id',activeDataset.dataset_id);return u.pathname+u.search}
function withDataset(p){if(!activeDataset?.dataset_id)return p;const sep=p.includes('?')?'&':'?';return p+sep+'dataset_id='+encodeURIComponent(activeDataset.dataset_id)}
const responseCache=new Map(), responseInflight=new Map();
async function api(p){const r=await fetch(datasetUrl(p));if(!r.ok)throw new Error(await r.text());return r.json()}
async function apiCached(p,ttl=120000){
  const url=datasetUrl(p),now=Date.now(),hit=responseCache.get(url);
  if(hit&&now-hit.time<ttl)return hit.data;
  if(responseInflight.has(url))return responseInflight.get(url);
  const job=fetch(url).then(async r=>{if(!r.ok)throw new Error(await r.text());const data=await r.json();responseCache.set(url,{time:Date.now(),data});return data}).finally(()=>responseInflight.delete(url));
  responseInflight.set(url,job);return job;
}
function datasetShort(){return activeDataset.label||'Selected dataset'}

function leagueThemeKey(d=activeDataset){
  const n=String((d&&((d.competition||'')+' '+(d.label||'')))||'').toLowerCase();
  if(n.includes('bundesliga'))return 'bundesliga';
  if(n.includes('la liga')||n.includes('laliga'))return 'laliga';
  if(n.includes('serie a'))return 'seriea';
  if(n.includes('ligue 1'))return 'ligue1';
  if(n.includes('champions')||n.includes('ucl'))return 'ucl';
  if(n.includes('world cup'))return 'worldcup';
  if(n.includes('premier'))return 'premier';
  return 'fil';
}
function applyLeagueTheme(d=activeDataset){
  const key=leagueThemeKey(d),root=document.documentElement;
  root.dataset.league=key;
  document.body.dataset.league=key;
}
async function initDatasets(){
  const sel=$('#datasetSelect');
  if(!sel)return;
  sel.disabled=true;
  sel.innerHTML='<option value="">Loading datasets…</option>';
  const fetchCatalogue=async(url,timeout=12000)=>{
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);
    try{
      const r=await fetch(url+'?v=245&t='+Date.now(),{signal:controller.signal,cache:'no-store',headers:{'Accept':'application/json'}});
      if(!r.ok)throw new Error(`${url} HTTP ${r.status}`);
      const data=await r.json();
      if(!Array.isArray(data))throw new Error(`${url} returned ${typeof data}, expected array`);
      return data.filter(d=>d&&typeof d==='object'&&d.dataset_id);
    }finally{clearTimeout(timer)}
  };
  let rows=[]; let lastErr=null;
  for(const url of ['/dataset-catalogue','/datasets']){
    try{rows=await fetchCatalogue(url);if(rows.length)break}catch(err){lastErr=err;console.warn('FIL catalogue attempt failed:',url,err)}
  }
  if(!rows.length){
    sel.disabled=false;
    sel.innerHTML='<option value="">Dataset catalogue failed — click to retry</option>';
    sel.onchange=()=>initDatasets();
    sel.onclick=()=>{if(sel.value==='')initDatasets()};
    const health=$('#health');if(health)health.textContent='Dataset catalogue failed · '+(lastErr?.message||'no installed datasets');
    return;
  }
  // Never expose legacy seasons in the current FIL product, even if old folders remain on disk.
  rows=rows.filter(d=>String(d.season||'').startsWith('2025')||String(d.season||'').startsWith('2026'));
  if(!rows.length){sel.innerHTML='<option value="">No 2025/26+ datasets installed</option>';return}
  const preferred=rows.find(d=>String(d.season).startsWith('2026')&&String(d.competition).toLowerCase().includes('premier'))||rows.find(d=>String(d.season).startsWith('2026'))||rows[0];
  sel.innerHTML=rows.map(d=>`<option value="${d.dataset_id}" ${d.dataset_id===preferred.dataset_id?'selected':''}>${d.label||`${d.competition} · ${d.season}`}${Number(d.matches||0)>0?' · '+Number(d.matches).toLocaleString()+' matches':''}</option>`).join('');
  sel.disabled=false;
  const apply=async()=>{
    const d=rows.find(x=>x.dataset_id===sel.value)||rows[0];if(!d)return;
    activeDataset=d;$('#datasetLabel').textContent=(d.label||`${d.competition} · ${d.season}`).toUpperCase();applyLeagueTheme(d);
    // Render the selected dataset immediately. Everything below is optional enrichment.
    const pb=document.querySelector('.provider b');if(pb)pb.textContent=d.provider||'FIL multi-provider';
    const health=$('#health');if(health)health.textContent=`${Number(d.matches||0)>0?Number(d.matches).toLocaleString()+' matches · ':''}v1.2.0`;
    compareIds=[];transferClubsLoaded=false;teamsLoaded=false;++matchRequestSeq;
    $('#profile')?.classList.add('hidden');$('#empty')?.classList.remove('hidden');if($('#compareBody'))$('#compareBody').innerHTML='';if($('#matchAnalysis'))$('#matchAnalysis').innerHTML='';
    api('/capabilities').then(cap=>{activeCapabilities=cap.capabilities||{};if(pb)pb.textContent=cap.provider||d.provider||'FIL multi-provider'}).catch(err=>console.warn('Capabilities unavailable',err));
    // Lazy-load only the section the user is actually looking at. v7.0.0 eagerly
    // rebuilt Match Lab plus the active section on every league change, which made
    // the whole shell feel as if it was reloading.
    if(activeView==='matches')loadMatches().catch(err=>console.warn('Matches unavailable for dataset',err));
    if(activeView==='home'){}if(activeView==='live-transfers')loadLiveTransfers();if(activeView==='scout')loadScout();if(activeView==='teams')loadTeams();if(activeView==='transfers')loadTransfer();if(activeView==='league')loadLeague();if(activeView==='rankings')loadRankings();if(activeView==='worldcup')loadWorldCup();
  };
  sel.onchange=()=>apply().catch(err=>console.error('Dataset switch failed',err));
  await apply();
 }

