function selectSearchPlayer(id,datasetId=activeDataset.dataset_id,name='',team=''){if(searchController){searchController.abort();searchController=null;}++searchRequestSeq;$('#results').innerHTML='';$('#search').value='';if(activeView==='compare')addCompare(id,datasetId);else if(name)openResolvedPlayer(name,team,datasetId);else openPlayer(id,datasetId)}
async function switchDatasetForPlayer(datasetId){
  if(!datasetId||datasetId===activeDataset?.dataset_id)return true;
  const sel=$('#datasetSelect'),opt=sel?[...sel.options].find(o=>o.value===datasetId):null;
  if(!opt){console.warn('Player dataset is not installed',datasetId);return false}
  sel.value=datasetId;sel.dispatchEvent(new Event('change'));
  const deadline=Date.now()+5000;
  while(activeDataset?.dataset_id!==datasetId&&Date.now()<deadline)await new Promise(r=>setTimeout(r,25));
  return activeDataset?.dataset_id===datasetId;
}
async function openPlayer(id,datasetId=null){
  const targetDataset=datasetId||activeDataset?.dataset_id;
  if(!(await switchDatasetForPlayer(targetDataset)))return;
  document.querySelector('nav button[data-view="players"]')?.click();
  await loadPlayer(Number(id),targetDataset);
}

async function resolveAndOpenPlayer(name,team='',preferredDataset=null){
  if(!name)return;
  try{
    const u=new URLSearchParams({name,team:team||'',dataset_id:preferredDataset||''});
    // Resolver is global by design: do not let datasetUrl() rewrite its identity search.
    const r=await fetch('/resolve-player?'+u.toString());
    if(!r.ok)throw new Error(await r.text());
    const hit=await r.json();
    await openPlayer(Number(hit.id),hit.dataset_id);
  }catch(err){
    console.error('FIL player identity resolution failed',err);
    document.querySelector('nav button[data-view="players"]')?.click();
    const box=$('#profile');$('#empty')?.classList.add('hidden');box?.classList.remove('hidden');
    if(box)box.innerHTML='<div class="method big">This player is known to FIL, but no statistical Player Lab record could be resolved from the installed datasets.</div>';
  }
}

async function openResolvedPlayer(name,team='',datasetId=null){
  // v4 universal UI hand-off: human identity -> atomic resolved profile -> render.
  // No UI surface is allowed to assume a dataset-local numeric ID is portable.
  try{
    const u=new URLSearchParams({name:name||'',team:team||'',dataset_id:datasetId||''});
    const r=await fetch('/resolve-player-profile?'+u.toString());
    if(!r.ok)throw new Error(await r.text());
    const profile=await r.json(),did=profile.dataset_id;
    if(!(await switchDatasetForPlayer(did)))throw new Error('Resolved dataset is not selectable');
    document.querySelector('nav button[data-view="players"]')?.click();
    return loadPlayer(Number(profile.id),did,profile);
  }catch(err){console.error('Resolved Player Lab hand-off failed',err);return resolveAndOpenPlayer(name,team,datasetId)}
}

async function openWonderkidPlayer(name,team='',datasetId=null,hintedId=null){return openResolvedPlayer(name,team,datasetId)}

async function openPlayerByName(name,team=''){return resolveAndOpenPlayer(name,team,activeDataset?.dataset_id)}

