function heatmapHtml(){return `<div class="heatmap-v2"><canvas id="seasonHeatCanvas" aria-label="Player season event density heatmap"></canvas></div>`}
function drawSeasonHeatmap(m){
  const canvas=$('#seasonHeatCanvas');if(!canvas)return;const shots=m.shots||[],rect=canvas.parentElement.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1),W=Math.max(560,Math.round(rect.width*dpr)),H=Math.round(W*.62);canvas.width=W;canvas.height=H;canvas.style.height=(H/dpr)+'px';
  const ctx=canvas.getContext('2d'),pad=26*dpr,x0=pad,y0=pad,pw=W-pad*2,ph=H-pad*2;ctx.fillStyle='#071b17';ctx.fillRect(0,0,W,H);ctx.fillStyle='#0a2a22';ctx.fillRect(x0,y0,pw,ph);
  // real pitch context so density has spatial meaning
  ctx.strokeStyle='rgba(181,220,205,.34)';ctx.lineWidth=1*dpr;ctx.strokeRect(x0,y0,pw,ph);ctx.beginPath();ctx.moveTo(x0+pw/2,y0);ctx.lineTo(x0+pw/2,y0+ph);ctx.stroke();ctx.beginPath();ctx.arc(x0+pw/2,y0+ph/2,ph*.12,0,Math.PI*2);ctx.stroke();
  const boxW=pw*.165,boxH=ph*.55,sixW=pw*.055,sixH=ph*.25;ctx.strokeRect(x0+pw-boxW,y0+(ph-boxH)/2,boxW,boxH);ctx.strokeRect(x0+pw-sixW,y0+(ph-sixH)/2,sixW,sixH);ctx.strokeRect(x0,y0+(ph-boxH)/2,boxW,boxH);ctx.strokeRect(x0,y0+(ph-sixH)/2,sixW,sixH);
  const pts=shots.map(e=>({x:Number(e.x),y:Number(e.y),xg:Number(e.xg||0)})).filter(e=>Number.isFinite(e.x)&&Number.isFinite(e.y));
  // compact Gaussian kernels per shot; avoids the giant single red rectangle from v1.1.1
  ctx.save();ctx.globalCompositeOperation='lighter';for(const e of pts){const px=x0+e.x/120*pw,py=y0+e.y/80*ph,r=(18+Math.sqrt(Math.max(0,e.xg))*15)*dpr,g=ctx.createRadialGradient(px,py,0,px,py,r);g.addColorStop(0,'rgba(255,80,55,.26)');g.addColorStop(.35,'rgba(255,194,55,.18)');g.addColorStop(.7,'rgba(73,217,161,.10)');g.addColorStop(1,'rgba(73,217,161,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);ctx.fill()}ctx.restore();
  for(const e of pts){const px=x0+e.x/120*pw,py=y0+e.y/80*ph;ctx.fillStyle='rgba(232,255,247,.52)';ctx.beginPath();ctx.arc(px,py,1.6*dpr,0,Math.PI*2);ctx.fill()}
}

