async function renderCompare(){const seq=++compareRequestSeq;let slots=$('#compareSlots'),body=$('#compareBody');if(!compareIds.length){slots.innerHTML='<div class="compare-empty">Search any player from the selected season to start comparing across leagues.</div>';body.innerHTML='';return}const refs=[...compareIds].map(parseCompareRef);let ps=await Promise.all(refs.map(r=>fetch(`/global-player/${encodeURIComponent(r.dataset_id)}/${r.id}`).then(x=>{if(!x.ok)throw new Error('compare player');return x.json()})));if(seq!==compareRequestSeq)return;slots.innerHTML=ps.map((p,i)=>`<div class="compare-chip"><b>${p.name}</b><span>${p.competition||''} · ${p.position_group} · ${fmt(p.minutes)} min</span><button data-rm="${i}">×</button></div>`).join('')+(compareIds.length<5?'<div class="compare-hint">+ search above to add another league/player</div>':'');$$('[data-rm]').forEach(b=>b.onclick=()=>{compareIds.splice(Number(b.dataset.rm),1);renderCompare()});if(ps.length<2){body.innerHTML='<div class="method big">Add one more player to generate the comparison table.</div>';return}const supported=['xg','shots','shot_assists','xa','xg_chain','xg_buildup','passes','passes_completed','carries','pressures','interceptions','duels'].filter(k=>ps.some(p=>p[k+'_p90']!=null && !(p.provider_name==='Understat'&&!['xg','shots','shot_assists','xa','xg_chain','xg_buildup'].includes(k))));body.innerHTML=`<div class="card compare-card"><div class="card-head"><b>Cross-league per-90 comparison</b><span>Percentiles stay relative to each player's own league + position peers</span></div><div class="compare-table" style="--compare-count:${ps.length}"><div class="ct-head">Metric</div>${ps.map(p=>`<div class="ct-head player">${p.name}<small>${p.competition||''} · ${p.position_group} peers</small></div>`).join('')}${supported.map(k=>`<div class="ct-label">${labels[k]}</div>${ps.map(p=>{const v=p[k+'_p90'],pct=p.percentiles?.[k+'_p90'];return `<div class="ct-value"><b>${v==null?'—':fmt(v)}</b><span>${pct==null?'—':'P'+pct}</span><i><em style="width:${pct||0}%"></em></i></div>`}).join('')}`).join('')}</div></div>`}


